create table products (`n id uuid primary key default gen_random_uuid(),`n slug text unique not null,`n title text not null,`n description text,`n price_cents int not null check (price_cents >= 0),`n preview_images text[] default '{}',`n file_path text not null,`n file_size_mb numeric,`n image_count int default 0,`n is_active boolean default true,`n created_at timestamptz default now()`n);`ncreate index idx_products_slug on products(slug);`ncreate index idx_products_active on products(is_active) where is_active = true;`ncreate table purchases (`n id uuid primary key default gen_random_uuid(),`n product_id uuid references products(id) on delete restrict not null,`n email text not null,`n stripe_session_id text unique not null,`n amount_cents int not null,`n currency text default 'usd',`n downloaded_at timestamptz,`n created_at timestamptz default now()`n);`ncreate index idx_purchases_email on purchases(email);`ncreate index idx_purchases_session on purchases(stripe_session_id);`ncreate table download_tokens (`n id uuid primary key default gen_random_uuid(),`n purchase_id uuid references purchases(id) on delete cascade not null,`n token text unique not null,`n expires_at timestamptz not null,`n used boolean default false,`n created_at timestamptz default now()`n);`ncreate index idx_tokens_token on download_tokens(token);`nalter table products enable row level security;`nalter table purchases enable row level security;`nalter table download_tokens enable row level security;`ncreate policy 'public read active products' on products for select using (is_active = true);`ncreate policy 'service role full purchases' on purchases for all using (auth.role() = 'service_role');`ncreate policy 'service role full tokens' on download_tokens for all using (auth.role() = 'service_role');